 return [['向左环绕',function(){turn(-.22,0,1)}],['向右环绕',function(){turn(.22,0,1)}],['俯视一点',function(){turn(0,-.16,1)}],['仰视一点',function(){turn(0,.16,1)}],['拉近',function(){turn(0,0,.8)}],['拉远',function(){turn(0,0,1.25)}]];
}
